INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000860090','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000860090","revision":1,"targetId":"80000000-0000-4000-8000-000000008609","prompt":"Für das neue Jahr hat sie sich ___, mehr Bücher zu lesen.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"She set a personal goal for the year.","de":"Sie setzte sich ein persönliches Jahresziel."},"slots":[{"id":"verb","label":"Verb oder Verbform","options":[{"id":"0","text":"vorbereitet"},{"id":"1","text":"vorgenommen"},{"id":"2","text":"entschuldigt"},{"id":"3","text":"erinnert"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"verb","optionId":"1"}]}],"explanation":{"en":"sich vornehmen means set oneself an intention or goal. She set a personal goal for the year.","de":"sich vornehmen bedeutet sich ein Ziel setzen. Sie setzte sich ein persönliches Jahresziel."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für das neue Jahr hat sie sich vorgenommen, mehr Bücher zu lesen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L735 (63110c9d40bfad30be0aa8e5401f41e8ac7fb37b1b8e054944ef35887fae9d9b), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
