INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000880030','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000880030","revision":1,"targetId":"80000000-0000-4000-8000-000000008803","prompt":"Am Sonntag möchten wir im Park ___ und die frische Luft genießen.","instruction":{"en":"Choose the expression or verb form that best completes the German sentence.","de":"Wähle den Ausdruck oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"The plan is a relaxed walk outdoors.","de":"Geplant ist ein gemütlicher Weg zu Fuß."},"slots":[{"id":"expression","label":"Ausdruck oder Verbform","options":[{"id":"0","text":"einkaufen gehen"},{"id":"1","text":"arbeiten gehen"},{"id":"2","text":"spazieren gehen"},{"id":"3","text":"schwimmen gehen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"expression","optionId":"2"}]}],"explanation":{"en":"spazieren gehen means go for a walk. The plan is a relaxed walk outdoors.","de":"spazieren gehen bedeutet zu Fuß einen Spaziergang machen. Geplant ist ein gemütlicher Weg zu Fuß."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Am Sonntag möchten wir im Park spazieren gehen und die frische Luft genießen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L754 (21ac2cbb617ac353d70bdf72212366562121829d42d270a677a5f183b066ba9f), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
